1	package vault
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"io/fs"
10		"os"
11		"path/filepath"
12		"sort"
13		"strings"
14	)
15	
16	// Snapshot is an immutable record of every name mapping in the repository at
17	// creation time. It only references existing content objects; no artifact
18	// bytes are copied.
19	type Snapshot struct {
20		Name    string           `json:"name"`
21		Entries map[string]Entry `json:"entries"`
22	}
23	
24	// SnapshotInfo summarizes a saved snapshot for listing.
25	type SnapshotInfo struct {
26		Name  string
27		Count int
28	}
29	
30	// CreateSnapshot records the current name mapping under the given snapshot
31	// name. The snapshot is written to a temporary file and renamed into place,
32	// so a crash leaves either the complete snapshot or none at all.
33	func (s *Store) CreateSnapshot(name string) (Snapshot, error) {
34		if err := validateName(name); err != nil {
35			return Snapshot{}, err
36		}
37		var snap Snapshot
38		err := s.withLock(true, func() error {
39			if err := s.initLocked(); err != nil {
40				return err
41			}
42			idx, err := s.load()
43			if err != nil {
44				return fmt.Errorf("cannot snapshot: current index is unreadable: %w", err)
45			}
46			path := s.snapshotPath(name)
47			if _, err := os.Stat(path); err == nil {
48				return fmt.Errorf("snapshot %q already exists", name)
49			} else if !errors.Is(err, os.ErrNotExist) {
50				return err
51			}
52			snap = Snapshot{Name: name, Entries: idx.Entries}
53			return s.saveSnapshot(path, snap)
54		})
55		if err != nil {
56			return Snapshot{}, err
57		}
58		return snap, nil
59	}
60	
61	// ListSnapshots returns every saved snapshot sorted by name. A repository
62	// with no snapshots yields an empty list.
63	func (s *Store) ListSnapshots() ([]SnapshotInfo, error) {
64		infos := []SnapshotInfo{}
65		err := s.withLock(false, func() error {
66			dir := s.snapshotsDir()
67			err := filepath.WalkDir(dir, func(path string, d fs.DirEntry, err error) error {
68				if err != nil {
69					return err
70				}
71				if d.IsDir() || !strings.HasSuffix(d.Name(), ".json") {
72					return nil
73				}
74				rel, err := filepath.Rel(dir, path)
75				if err != nil {
76					return err
77				}
78				name := strings.TrimSuffix(filepath.ToSlash(rel), ".json")
79				data, err := os.ReadFile(path)
80				if err != nil {
81					return err
82				}
83				var snap Snapshot
84				if err := json.Unmarshal(data, &snap); err != nil {
85					return fmt.Errorf("snapshot %q is corrupted: %w", name, err)
86				}
87				infos = append(infos, SnapshotInfo{Name: name, Count: len(snap.Entries)})
88				return nil
89			})
90			if errors.Is(err, os.ErrNotExist) {
91				return nil
92			}
93			return err
94		})
95		if err != nil {
96			return nil, err
97		}
98		sort.Slice(infos, func(i, j int) bool { return infos[i].Name < infos[j].Name })
99		return infos, nil
100	}
101	
102	// RestoreSnapshot replaces the current name mapping with the snapshot's
103	// recorded mapping in a single atomic index write. The current index is never
104	// read, so restore works even when it is corrupted. The selected snapshot
105	// record must be a complete, well-formed document whose recorded name equals
106	// the selected snapshot name in full (a record nested under "releases/stable"
107	// must itself say "releases/stable", never just "stable") and whose entries
108	// mapping is present and an object ({} is a legitimate empty snapshot; a
109	// missing, null, or non-object entries field is corruption, never an empty
110	// mapping). Every referenced object is checked for existence, size, and
111	// SHA-256 before the mapping is swapped; any failure leaves the current
112	// mapping's bytes and all snapshots and objects untouched, even when the
113	// current mapping itself is already corrupted.
114	func (s *Store) RestoreSnapshot(name string) error {
115		if err := validateName(name); err != nil {
116			return err
117		}
118		return s.withLock(true, func() error {
119			if err := s.initLocked(); err != nil {
120				return err
121			}
122			snap, err := s.loadSnapshotRecord(name)
123			if err != nil {
124				return err
125			}
126			for _, entry := range snap.Entries {
127				if err := s.verifyObject(entry); err != nil {
128					return fmt.Errorf("cannot restore snapshot %q: object for %q: %w", name, entry.Name, err)
129				}
130			}
131			return s.save(index{Entries: snap.Entries})
132		})
133	}
134	
135	// decodeSnapshotRecord parses one snapshot record without touching the
136	// repository. wantName is the full snapshot name the record is selected or
137	// filed under and must record verbatim.
138	//
139	// A valid record is exactly one JSON object — never the bare null — with no
140	// duplicate or unknown fields and no trailing data, carrying:
141	//
142	//   - "name": present and a string equal to wantName, including every level of
143	//     a multi-level name; a missing, wrong-type, or merely-suffixed name
144	//     (record "stable" under "releases/stable") is refused;
145	//   - "entries": present and a JSON object. {} is a legitimate empty mapping;
146	//     a missing field, a null, an array, or any non-object value is
147	//     corruption rather than zero entries.
148	//
149	// Every entry is then checked with validateEntryRecord. The errors
150	// distinguish a missing entries mapping, a mismatching recorded name, and a
151	// malformed document so callers can tell record corruption apart from a
152	// snapshot that simply does not exist (that distinction is made by the
153	// caller, which checks the file before reading it).
154	func decodeSnapshotRecord(data []byte, wantName string) (Snapshot, error) {
155		if err := rejectDuplicateKeys(data); err != nil {
156			return Snapshot{}, fmt.Errorf("malformed record: %w", err)
157		}
158		// The document must be a JSON object: a bare null, array, or primitive is
159		// a malformed record, never an empty snapshot.
160		if trimmed := bytes.TrimSpace(data); len(trimmed) == 0 || trimmed[0] != '{' {
161			return Snapshot{}, errors.New("malformed record: expected a JSON object with name and entries")
162		}
163		var raw struct {
164			Name    *string          `json:"name"`
165			Entries *json.RawMessage `json:"entries"`
166		}
167		dec := json.NewDecoder(bytes.NewReader(data))
168		dec.DisallowUnknownFields()
169		if err := dec.Decode(&raw); err != nil {
170			return Snapshot{}, fmt.Errorf("malformed record: %w", err)
171		}
172		if tok, err := dec.Token(); err != io.EOF {
173			if err == nil {
174				return Snapshot{}, fmt.Errorf("malformed record: unexpected trailing content after the snapshot object (%v)", tok)
175			}
176			return Snapshot{}, fmt.Errorf("malformed record: %w", err)
177		}
178		if raw.Name == nil {
179			return Snapshot{}, errors.New("malformed record: missing snapshot name")
180		}
181		if *raw.Name != wantName {
182			return Snapshot{}, fmt.Errorf("recorded name %q does not match snapshot %q", *raw.Name, wantName)
183		}
184		if raw.Entries == nil {
185			return Snapshot{}, errors.New("record is missing its entries mapping")
186		}
187		entriesJSON := *raw.Entries
188		if string(bytes.TrimSpace(entriesJSON)) == "null" {
189			return Snapshot{}, errors.New("record is missing its entries mapping")
190		}
191		var entries map[string]Entry
192		if err := json.Unmarshal(entriesJSON, &entries); err != nil {
193			return Snapshot{}, fmt.Errorf("entries mapping is malformed: %w", err)
194		}
195		if entries == nil {
196			return Snapshot{}, errors.New("record is missing its entries mapping")
197		}
198		for key, entry := range entries {
199			if err := validateEntryRecord(key, entry); err != nil {
200				return Snapshot{}, err
201			}
202		}
203		return Snapshot{Name: *raw.Name, Entries: entries}, nil
204	}
205	
206	func (s *Store) saveSnapshot(path string, snap Snapshot) error {
207		data, err := json.MarshalIndent(snap, "", "  ")
208		if err != nil {
209			return err
210		}
211		data = append(data, '\n')
212		if err := s.ensureSnapshotParent(path); err != nil {
213			return err
214		}
215		dir := filepath.Dir(path)
216		tmp, err := os.CreateTemp(dir, ".snapshot-*")
217		if err != nil {
218			return err
219		}
220		tmpName := tmp.Name()
221		defer os.Remove(tmpName)
222		if _, err := tmp.Write(data); err != nil {
223			tmp.Close()
224			return err
225		}
226		if err := tmp.Close(); err != nil {
227			return err
228		}
229		return os.Rename(tmpName, path)
230	}
231	
232	// ensureSnapshotParent creates the parent directories of a snapshot record one
233	// component at a time, refusing to follow symbolic links. Without this a nested
234	// snapshot name such as "evil/x" could be redirected through a pre-created
235	// snapshots/evil symlink to write outside the repository.
236	func (s *Store) ensureSnapshotParent(path string) error {
237		base := s.snapshotsDir()
238		rel, err := filepath.Rel(base, filepath.Dir(path))
239		if err != nil {
240			return err
241		}
242		if rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
243			return errors.New("snapshot path escapes the snapshots directory")
244		}
245		// The base directory itself must exist and be a real directory, even for a
246		// top-level snapshot (a freshly initialized repository has no snapshots/).
247		cur := base
248		if err := ensureRealDir(cur); err != nil {
249			return err
250		}
251		if rel == "." {
252			return nil
253		}
254		for _, component := range strings.Split(rel, string(filepath.Separator)) {
255			next := filepath.Join(cur, component)
256			if err := ensureRealDir(next); err != nil {
257				return err
258			}
259			cur = next
260		}
261		return nil
262	}
263	
264	// ensureRealDir makes sure path is a real directory, creating it if absent,
265	// and refuses an existing symlink or non-directory.
266	func ensureRealDir(path string) error {
267		info, err := os.Lstat(path)
268		switch {
269		case errors.Is(err, os.ErrNotExist):
270			if err := os.Mkdir(path, 0o755); err != nil && !errors.Is(err, os.ErrExist) {
271				return err
272			}
273			info, err = os.Lstat(path)
274			if err != nil {
275				return err
276			}
277		case err != nil:
278			return err
279		}
280		if info.Mode()&os.ModeSymlink != 0 {
281			return fmt.Errorf("repository path %q is a symbolic link", path)
282		}
283		if !info.IsDir() {
284			return fmt.Errorf("repository path %q is not a directory", path)
285		}
286		return nil
287	}
288	
289	func (s *Store) snapshotsDir() string { return filepath.Join(s.root, "snapshots") }
290	
291	func (s *Store) snapshotPath(name string) string {
292		return filepath.Join(s.snapshotsDir(), filepath.FromSlash(name)+".json")
293	}
294	
295	func isDigest(digest string) bool {
296		if len(digest) != 64 {
297			return false
298		}
299		for _, c := range digest {
300			if (c < '0' || c > '9') && (c < 'a' || c > 'f') {
301				return false
302			}
303		}
304		return true
305	}
